WITH booking_ids AS (SELECT id, row_number() OVER (ORDER BY created_at) as rn FROM bookings WHERE status = 'completed'),
city_data AS (SELECT * FROM (VALUES 
('Denver', -104.9903, 39.7392, 1), ('Aurora', -104.8319, 39.7294, 2), ('Lakewood', -105.0814, 39.7047, 3), ('Arvada', -105.0875, 39.8028, 4), ('Westminster', -105.0372, 39.8367, 5), ('Thornton', -104.9719, 39.868, 6), ('Centennial', -104.8769, 39.5807, 7), ('Boulder', -105.2705, 40.015, 8), ('Littleton', -105.0166, 39.6133, 9), ('Broomfield', -105.0897, 39.9205, 10), ('Northglenn', -104.9872, 39.8858, 11), ('Commerce City', -104.9333, 39.8083, 12), ('Englewood', -104.9878, 39.6478, 13), ('Brighton', -104.8208, 39.9853, 14), ('Castle Rock', -104.8561, 39.3722, 15), ('Parker', -104.7611, 39.5186, 16), ('Highlands Ranch', -104.9694, 39.5539, 17), ('Longmont', -105.1019, 40.1672, 18), ('Lafayette', -105.0897, 39.9936, 19), ('Louisville', -105.1319, 39.9778, 20), ('Erie', -105.05, 40.0503, 21), ('Superior', -105.1686, 39.9528, 22), ('Golden', -105.2211, 39.7555, 23)
) AS t(name, lng, lat, idx))
UPDATE bookings b SET 
service_address = cd.name || ', CO',
longitude = cd.lng + (random() - 0.5) * 0.038,
latitude = cd.lat + (random() - 0.5) * 0.029
FROM booking_ids bi, city_data cd 
WHERE b.id = bi.id AND cd.idx = ((bi.rn - 1) % 23) + 1;
